#[test]
fn golden_state() {
    {
        let s = State64Bit::new(5, 7, 2, 3);
        assert_eq!((s.pattern_id, s.sample_id, s.pixel_id), (0xac564b07, 3, 1797));
        let d = s.pixel_decorrelate();
        assert_eq!((d.pattern_id, d.sample_id, d.pixel_id), (0x8059e181, 3, 1797));
    }
    {
        let s = State64Bit::new(200, 100, 1, 65536);
        assert_eq!((s.pattern_id, s.sample_id, s.pixel_id), (0xac564b07, 0, 25800));
        let d = s.pixel_decorrelate();
        assert_eq!((d.pattern_id, d.sample_id, d.pixel_id), (0xa967d160, 0, 25800));
    }
    {
        let s = State64Bit::new(256, 3, 0, 70000);
        assert_eq!((s.pattern_id, s.sample_id, s.pixel_id), (0xac564b06, 4464, 768));
        let d = s.pixel_decorrelate();
        assert_eq!((d.pattern_id, d.sample_id, d.pixel_id), (0x2b0c3f43, 4464, 768));
    }
}

